import{_ as a,o as e,c as o,ae as r}from"./chunks/framework.Dh1jimFm.js";const h=JSON.parse('{"title":"Creating Prompts","description":"","frontmatter":{},"headers":[],"relativePath":"ai-translation/prompts.md","filePath":"ai-translation/prompts.md"}'),l={name:"ai-translation/prompts.md"};function i(n,t,s,c,p,m){return e(),o("div",null,t[0]||(t[0]=[r('<h1 id="creating-prompts" tabindex="-1">Creating Prompts <a class="header-anchor" href="#creating-prompts" aria-label="Permalink to &quot;Creating Prompts&quot;">​</a></h1><p>Prompts control how the AI translates (tone, domain, rules, formatting).</p><h2 id="what-makes-a-good-translation-prompt" tabindex="-1">What makes a good translation prompt <a class="header-anchor" href="#what-makes-a-good-translation-prompt" aria-label="Permalink to &quot;What makes a good translation prompt&quot;">​</a></h2><ul><li>Target audience and tone (formal/informal)</li><li>Domain constraints (legal, medical, technical)</li><li>Rules for numbers, punctuation, terminology</li><li>Instructions to preserve tags and placeholders</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If your text contains formatting or CAT tool tags, instruct the model to preserve them exactly.</p></div><h2 id="quick-checklist" tabindex="-1">Quick checklist <a class="header-anchor" href="#quick-checklist" aria-label="Permalink to &quot;Quick checklist&quot;">​</a></h2><ul><li>Specify the language direction (source → target)</li><li>Specify style and audience (formal/informal, US/UK spelling, etc.)</li><li>Tell the model what to do with <strong>tags/placeholders</strong> (keep, don’t reorder, don’t delete)</li><li>Tell the model what to do with terminology (use glossary terms when provided)</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./prompt-library.html">Prompt Manager</a></li></ul>',9)]))}const u=a(l,[["render",i]]);expor